import { formatFileSize } from './format';

describe('formatFileSize', () => {
  it('0 / 空值返回 0 B', () => {
    expect(formatFileSize(0)).toBe('0 B');
    expect(formatFileSize(null)).toBe('0 B');
    expect(formatFileSize(undefined)).toBe('0 B');
  });

  it('字节级取整', () => {
    expect(formatFileSize(512)).toBe('512 B');
    expect(formatFileSize(1023)).toBe('1023 B');
  });

  it('KB 及以上保留 1 位小数（产品契约：整数值也输出 x.0，与 React 对标一致）', () => {
    expect(formatFileSize(1024)).toBe('1.0 KB');
    expect(formatFileSize(1536)).toBe('1.5 KB');
    expect(formatFileSize(1024 * 1024)).toBe('1.0 MB');
    expect(formatFileSize(1024 ** 3)).toBe('1.0 GB');
    expect(formatFileSize(1024 ** 4)).toBe('1.0 TB');
  });

  it('数值 >=100 取整显示', () => {
    expect(formatFileSize(102_400)).toBe('100 KB');
    expect(formatFileSize(1024 * 1024 * 100)).toBe('100 MB');
  });

  it('超大容量封顶 PB 且不越界', () => {
    expect(formatFileSize(1024 ** 6)).toBe('1024 PB');
    expect(formatFileSize(Number.MAX_SAFE_INTEGER)).toMatch(/PB$/);
  });
});
